// Generated by Automated Quality Gate; review before merging.
const fs = require('fs');
const path = require('path');

describe('Counter Application', () => {
  let countElement;
  let addButton;

  beforeEach(() => {
    const html = fs.readFileSync(path.resolve(__dirname, '../src/index.html'), 'utf8');
    document.documentElement.innerHTML = html;

    countElement = document.querySelector("#count");
    addButton = document.querySelector("#add");

    jest.resetModules();
    require('../../src/app');
  });

  afterEach(() => {
    document.body.innerHTML = '';
  });

  test('should initialize count at 0', () => {
    expect(countElement.textContent).toBe('0');
  });

  test('should increment count when add button is clicked', () => {
    addButton.click();
    expect(countElement.textContent).toBe('1');
    
    addButton.click();
    expect(countElement.textContent).toBe('2');
  });

  test('should handle multiple rapid clicks correctly', () => {
    for (let i = 0; i < 5; i++) {
      addButton.click();
    }
    expect(countElement.textContent).toBe('5');
  });

  test('should update the DOM element content directly', () => {
    const initialText = countElement.textContent;
    addButton.click();
    expect(countElement.textContent).not.toBe(initialText);
    expect(countElement.textContent).toBe('1');
  });
});
